-- Generated by `npm run content:seed`. Do not edit by hand.
-- Source: src/content/*. 19 scenarios.

insert into public.scenarios (
  id, kind, title, summary, setting,
  role_relevance, rank_relevance, primary_dimensions,
  estimated_minutes, branching_tree
) values
  (
    'calib-quiet-patrol-meeting',
    'calibration'::public.scenario_kind,
    'Nobody Answers',
    'You ask your patrol a question and get silence.',
    'Patrol corner, Tuesday troop meeting',
    array['PL', 'APL', 'SPL']::public.leadership_role[],
    array['scout', 'tenderfoot', 'second_class', 'first_class', 'star', 'life', 'eagle']::public.scout_rank[],
    array['communication']::text[],
    1,
    '{"version":1,"root":"ask","nodes":{"ask":{"id":"ask","type":"decision","prompt":"Your patrol is sitting in a circle. You ask, \"So who wants to handle food for the campout?\" Six scouts look at the floor. Nobody says anything for about ten seconds.","choices":[{"id":"wait-it-out","text":"Wait. Let the silence sit until someone volunteers.","deltas":{"communication":-1},"coaching":{"text":"Silence is a real tool, but an open question to a whole group usually gets nothing. The scouts are not refusing — they are waiting to see if it lands on someone else.","principle":"Open questions land on nobody"},"next":"wrap"},{"id":"name-and-ask","text":"Say, \"Marcus, you did food last spring and it went well. Want it again, or want to teach someone else to do it?\"","deltas":{"communication":3},"coaching":{"text":"Naming one scout turns a question nobody owns into a question one person has to answer. Offering the teaching option makes it a step up rather than the same chore twice.","edge_stage":"enable","principle":"Ask a person, not a room"},"next":"wrap"},{"id":"just-do-it","text":"Say, \"Fine, I will do food,\" and move to the next item.","deltas":{"communication":-2,"delegation":-1},"coaching":{"text":"This ends the silence and teaches the patrol that silence works. Next meeting the pause will be longer, because waiting you out is now the cheapest option.","principle":"Do not reward the wait"},"next":"wrap"},{"id":"break-it-down","text":"Say, \"Okay, food is really three jobs — menu, shopping, and cooler. Who wants the smallest one?\"","deltas":{"communication":2,"planning":1},"coaching":{"text":"Breaking one intimidating job into three visible pieces lowers what a scout has to say yes to. It also shows the patrol what the job actually involves.","edge_stage":"explain","principle":"Shrink the ask"},"next":"wrap"}]},"wrap":{"id":"wrap","type":"outcome","prompt":"The meeting moves on.","debrief":"How you ask decides what you get. Specific beats general, and a named scout beats an open room almost every time."}}}'::jsonb
  ),
  (
    'calib-tent-argument',
    'calibration'::public.scenario_kind,
    'Two Scouts, One Tent',
    'An argument over tent assignments is getting loud.',
    'Friday night setup, district camporee',
    array['PL', 'APL', 'SPL']::public.leadership_role[],
    array['tenderfoot', 'second_class', 'first_class', 'star', 'life', 'eagle']::public.scout_rank[],
    array['conflict_resolution']::text[],
    1,
    '{"version":1,"root":"flare","nodes":{"flare":{"id":"flare","type":"decision","prompt":"Tents are half up. Jordan and Eli are arguing about who is tenting with whom, loud enough that the next campsite over is watching. Neither one is backing down.","choices":[{"id":"order-it","text":"Say, \"Jordan, you are with Eli. Done,\" and walk away.","deltas":{"conflict_resolution":-2},"coaching":{"text":"It stops the noise and settles nothing. Whatever is actually going on between them comes back at breakfast, and now it comes back with you attached to it.","principle":"Loud is a symptom"},"next":"wrap"},{"id":"split-and-ask","text":"Pull each one aside separately and ask what is going on.","deltas":{"conflict_resolution":3,"communication":1},"coaching":{"text":"Separating them drops the audience, which is usually half of why it got loud. You also get two versions of the story before you decide anything.","principle":"Separate, then listen"},"next":"wrap"},{"id":"get-adult","text":"Go get the Scoutmaster.","deltas":{"conflict_resolution":-1,"initiative":-2},"coaching":{"text":"A tent argument is inside what a patrol leader handles. Save the adults for safety, health, and anything that has stopped being a scout problem.","principle":"Handle your own patrol first"},"next":"wrap"},{"id":"joke-it-off","text":"Make a joke about it and hope they drop it.","deltas":{"conflict_resolution":-1,"communication":1},"coaching":{"text":"Humour can lower the temperature, and that is worth something. It does not answer the question they are actually fighting about, so be ready for round two.","principle":"Defusing is not resolving"},"next":"wrap"}]},"wrap":{"id":"wrap","type":"outcome","prompt":"Tents get finished, one way or another.","debrief":"Most patrol conflict is smaller than it sounds and is mostly about being heard. Getting the audience out of it is usually step one."}}}'::jsonb
  ),
  (
    'calib-gear-before-friday',
    'calibration'::public.scenario_kind,
    'Gear Before Friday',
    'Patrol gear has to be checked out and you have four scouts.',
    'Tuesday meeting, three days before the campout',
    array['PL', 'APL', 'SPL']::public.leadership_role[],
    array['tenderfoot', 'second_class', 'first_class', 'star', 'life', 'eagle']::public.scout_rank[],
    array['delegation']::text[],
    1,
    '{"version":1,"root":"assign","nodes":{"assign":{"id":"assign","type":"decision","prompt":"Patrol gear needs pulling from the trailer before Friday: two tents, the patrol box, a stove, and two water jugs. You have four scouts in front of you and about eight minutes left in the meeting.","choices":[{"id":"do-it-yourself","text":"Handle it yourself Thursday. It is faster than explaining it.","deltas":{"delegation":-3,"initiative":1},"coaching":{"text":"It is faster this once, and then it is your job forever. Every time you absorb a task, the patrol learns that gear is the PL problem.","principle":"Fast now, stuck later"},"next":"wrap"},{"id":"named-pairs","text":"Split it: two scouts on tents, one on the patrol box, one on stove and jugs. Say each name out loud.","deltas":{"delegation":3,"planning":1},"coaching":{"text":"Named jobs with a named deadline are the whole trick. Nobody can assume someone else has the jugs when the jugs have a name on them.","edge_stage":"enable","principle":"A job with no name has no owner"},"next":"wrap"},{"id":"group-ask","text":"Say, \"Everybody grab something from the trailer Thursday,\" and trust them.","deltas":{"delegation":-1,"communication":-1},"coaching":{"text":"Trust is right, the instruction is not. \"Everybody grab something\" reliably produces three stoves and no tents.","principle":"Specific beats trusting"},"next":"wrap"},{"id":"ask-who-wants","text":"Ask who wants what, then fill the leftovers yourself.","deltas":{"delegation":2,"communication":1},"coaching":{"text":"Letting scouts pick raises the odds they follow through. Just make sure the leftovers get a name too, instead of quietly becoming yours.","principle":"Choice raises follow-through"},"next":"wrap"}]},"wrap":{"id":"wrap","type":"outcome","prompt":"The meeting closes.","debrief":"Delegating is not getting out of work. It is making sure the work has an owner who is not you."}}}'::jsonb
  ),
  (
    'calib-forecast-turns',
    'calibration'::public.scenario_kind,
    'The Forecast Turns',
    'Rain moves into the weekend forecast Thursday night.',
    'Thursday evening, day before departure',
    array['PL', 'APL', 'SPL']::public.leadership_role[],
    array['second_class', 'first_class', 'star', 'life', 'eagle']::public.scout_rank[],
    array['planning']::text[],
    1,
    '{"version":1,"root":"forecast","nodes":{"forecast":{"id":"forecast","type":"decision","prompt":"You check the forecast Thursday night. Saturday went from clear to rain most of the day. The plan was an all-day hike, and the patrol packed for sun.","choices":[{"id":"wait-and-see","text":"Say nothing. Forecasts change, and you will deal with it there.","deltas":{"planning":-2,"initiative":-1},"coaching":{"text":"Forecasts do change, but the cost of being wrong is lopsided. If you say something and it stays dry, a few scouts carry rain gear for nothing.","principle":"Weigh the cost of being wrong"},"next":"wrap"},{"id":"text-the-change","text":"Message the patrol tonight: rain gear is now required, and pack a dry set of clothes in a bag.","deltas":{"planning":2,"communication":2},"coaching":{"text":"Tonight is the only time this message is useful, because tomorrow their bags are packed. Naming the specific items beats saying \"it might rain\".","principle":"Information has an expiry time"},"next":"wrap"},{"id":"rework-plan","text":"Message the patrol about rain gear, and bring a shorter loop hike to the Friday PLC as a backup.","deltas":{"planning":3,"communication":1,"initiative":1},"coaching":{"text":"Two moves: gear so the day is survivable, and an alternate plan so it is still worth doing. Bringing the backup to the PLC instead of deciding alone keeps the other leaders in it.","edge_stage":"guide","principle":"Have the second plan ready"},"next":"wrap"},{"id":"cancel","text":"Push to cancel the hike and stay in camp.","deltas":{"planning":-1},"coaching":{"text":"Rain by itself is not a reason to cancel — scouts hike in rain all the time. Save cancellation for lightning, real cold with wet gear, or trail conditions that turn dangerous.","principle":"Adjust before you cancel"},"next":"wrap"}]},"wrap":{"id":"wrap","type":"outcome","prompt":"Friday comes.","debrief":"Planning is mostly noticing the thing that changed while there is still time to do something about it."}}}'::jsonb
  ),
  (
    'calib-after-dinner-mess',
    'calibration'::public.scenario_kind,
    'After Dinner',
    'The campsite is a mess and nothing is on the duty roster for it.',
    'Saturday evening, patrol campsite',
    array['PL', 'APL', 'SPL']::public.leadership_role[],
    array['scout', 'tenderfoot', 'second_class', 'first_class', 'star', 'life', 'eagle']::public.scout_rank[],
    array['initiative']::text[],
    1,
    '{"version":1,"root":"mess","nodes":{"mess":{"id":"mess","type":"decision","prompt":"Dinner is done. The cook crew is washing up, but there are wrappers by the fire ring, a stove left out, and someone''s water bottle in the dirt. None of it is on the duty roster. Scouts are drifting toward the campfire.","choices":[{"id":"not-my-job","text":"Leave it. It is not on the roster and the cook crew will probably get it.","deltas":{"initiative":-3},"coaching":{"text":"The roster covers the predictable work. The gap between the roster and what the campsite actually needs is exactly where leadership shows up.","principle":"The roster is a floor, not a ceiling"},"next":"wrap"},{"id":"quiet-fix","text":"Pick it all up yourself without saying anything.","deltas":{"initiative":2,"delegation":-2},"coaching":{"text":"You solved tonight. Nobody else learned that the site needed a sweep, so you will be doing it again tomorrow night.","principle":"Doing it alone teaches nobody"},"next":"wrap"},{"id":"call-two-minutes","text":"Say, \"Two minutes, everyone grabs three things, then campfire,\" and start picking up.","deltas":{"initiative":3,"delegation":2,"communication":1},"coaching":{"text":"A short time box and a clear number make it something scouts will actually do on the way past. Starting yourself while you say it is the demonstrate step.","edge_stage":"demonstrate","principle":"Time box it and start"},"next":"wrap"},{"id":"tell-cook-crew","text":"Tell the cook crew to get it when they finish dishes.","deltas":{"initiative":-1,"delegation":1},"coaching":{"text":"It has an owner now, which is better than nothing. It also loads more work onto the two scouts already working while five walk past.","principle":"Watch who you keep loading"},"next":"wrap"}]},"wrap":{"id":"wrap","type":"outcome","prompt":"The fire gets lit.","debrief":"Initiative is mostly noticing. The scouts who get asked to lead are usually the ones already picking things up."}}}'::jsonb
  ),
  (
    'calib-new-scout-alone',
    'calibration'::public.scenario_kind,
    'The New Guy',
    'A new scout has been standing by himself for twenty minutes.',
    'Saturday afternoon, first campout of the year',
    array['PL', 'APL', 'SPL']::public.leadership_role[],
    array['scout', 'tenderfoot', 'second_class', 'first_class', 'star', 'life', 'eagle']::public.scout_rank[],
    array['communication', 'initiative']::text[],
    1,
    '{"version":1,"root":"alone","nodes":{"alone":{"id":"alone","type":"decision","prompt":"Theo crossed over from the pack six weeks ago. This is his first campout. Everyone else is throwing a football or messing with the fire, and he has been standing near the tents on his own for about twenty minutes.","choices":[{"id":"leave-him","text":"Leave him be. Some people want space, and he has not asked for anything.","deltas":{"initiative":-2,"communication":-1},"coaching":{"text":"A new eleven-year-old on his first campout almost never asks. Checking costs you thirty seconds and tells you which it actually is.","principle":"New scouts do not ask"},"next":"wrap"},{"id":"general-invite","text":"Call over, \"Theo, come hang out with us.\"","deltas":{"communication":1,"initiative":1},"coaching":{"text":"Better than nothing, but it hands him the hard part — walking into a group that is already going. He will probably say he is fine.","principle":"Do not make him cross the gap"},"next":"wrap"},{"id":"give-him-a-job","text":"Walk over and say, \"I need a hand splitting kindling — come on,\" then introduce him to whoever is at the fire.","deltas":{"communication":3,"initiative":3},"coaching":{"text":"A job gives him a reason to be standing there and something to do with his hands. Handing him off to the fire group means you are not the only person he knows by dinner.","edge_stage":"guide","principle":"A job beats an invitation"},"next":"wrap"},{"id":"tell-apl","text":"Ask your APL to go include him.","deltas":{"communication":1,"delegation":2,"initiative":-1},"coaching":{"text":"Using your APL is legitimate and it is not a dodge. Just be honest about whether you delegated it or avoided it.","principle":"Delegate the task, not the discomfort"},"next":"wrap"}]},"wrap":{"id":"wrap","type":"outcome","prompt":"Dinner gets started.","debrief":"Most of the job is noticing one scout who is not doing fine, and doing something small about it early."}}}'::jsonb
  ),
  (
    'dish-duty-drift',
    'training'::public.scenario_kind,
    'Dish Duty Drift',
    'A scout in your patrol has skipped cleanup twice this weekend.',
    'Sunday morning, second day of a fall campout',
    array['PL', 'APL']::public.leadership_role[],
    array['second_class', 'first_class', 'star', 'life']::public.scout_rank[],
    array['conflict_resolution', 'delegation']::text[],
    4,
    '{"version":1,"root":"notice","nodes":{"notice":{"id":"notice","type":"decision","prompt":"Cole is on the duty roster for cleanup both nights. Friday he disappeared to the latrine and came back when the pots were done. Last night he did the same thing. Two other scouts covered for him and one of them just said something to you about it.","speaker":"Ramon","line":"\"I am not doing his pots again tonight.\"","choices":[{"id":"public-callout","text":"Say it at the patrol site where everyone can hear: \"Cole, you are on dishes and you keep bailing.\"","deltas":{"conflict_resolution":-2,"communication":-1},"coaching":{"text":"Correcting a scout in front of his patrol turns a work problem into a status problem, and he will defend his status before he fixes the work. Praise can be public; correction almost never should be.","principle":"Correct in private"},"next":"public-reaction"},{"id":"pull-aside","text":"Wait until after breakfast, walk over to him away from the others, and bring it up.","deltas":{"conflict_resolution":2,"communication":2},"coaching":{"text":"No audience means he does not have to protect anything, which is most of what makes these conversations go badly. It also signals you are handling it rather than staging it.","principle":"Drop the audience first"},"next":"aside-opening"},{"id":"quiet-reassign","text":"Move Cole off dishes on tonight''s roster and put Ramon on it instead. Avoid the conversation.","deltas":{"delegation":-2,"conflict_resolution":-2,"planning":1},"coaching":{"text":"The pots get washed and the actual problem gets bigger. You have also just told the scout who complained that the reward for doing his job is more work.","principle":"Do not tax the reliable"},"next":"reassign-fallout"}]},"public-reaction":{"id":"public-reaction","type":"decision","prompt":"Cole goes red. \"I did dishes Friday. Ramon just wants to be in charge.\" Two scouts laugh. Everyone is watching you now instead of packing.","choices":[{"id":"double-down","text":"Hold your ground in front of everyone: \"You did not, and you know it.\"","deltas":{"conflict_resolution":-3,"communication":-1},"coaching":{"text":"Now it is about which of you is right in front of witnesses, and no version of that ends with clean pots. Being correct is not the same as getting the outcome.","principle":"Winning the exchange is not the goal"},"next":"rough-landing"},{"id":"move-it-private","text":"Say, \"Fair — let us talk about it over by the trailer,\" and walk away from the group.","deltas":{"conflict_resolution":2,"communication":2},"coaching":{"text":"You cannot unstart it, but you can end the public part in one sentence. Taking the blame off him in front of the others makes the private conversation possible.","principle":"You can always leave the audience"},"next":"aside-opening"},{"id":"drop-it","text":"Say, \"Whatever, forget it,\" and go back to packing.","deltas":{"conflict_resolution":-1,"initiative":-2},"coaching":{"text":"You raised it, lost the room, and dropped it. The patrol now knows that pushing back works, and Ramon knows nothing is coming.","principle":"Do not start what you will not finish"},"next":"rough-landing"}]},"aside-opening":{"id":"aside-opening","type":"decision","prompt":"It is just the two of you by the trailer. Cole is looking at the ground, arms crossed, waiting for you to start.","choices":[{"id":"ask-open","text":"Say, \"You have been off for dishes twice. What is going on?\" — then stop talking.","deltas":{"conflict_resolution":3,"communication":3},"coaching":{"text":"Naming the fact and then going quiet gives him room to say the real reason, which is often not what you assumed. The silence after the question is the part most people skip.","edge_stage":"guide","principle":"Name the fact, then be quiet"},"next":"reason-surfaces"},{"id":"state-standard","text":"Say, \"Everyone does their roster job. You are on pots tonight and I will be there.\"","deltas":{"conflict_resolution":1,"communication":2,"delegation":1},"coaching":{"text":"Clear, fair, and it applies to everyone rather than singling him out. You may still be solving the wrong problem if there is a reason behind it.","edge_stage":"explain","principle":"Same standard for everyone"},"next":"reason-surfaces"},{"id":"soft-pass","text":"Say, \"Just try to be around at cleanup, okay?\" and leave it there.","deltas":{"conflict_resolution":-1,"communication":-2},"coaching":{"text":"You had the private conversation and then did not actually say anything in it. \"Try to be around\" is not a standard he can meet or miss.","principle":"Vague asks get vague results"},"next":"soft-landing"}]},"reason-surfaces":{"id":"reason-surfaces","type":"decision","prompt":"Cole shrugs. \"I do not know how you guys do the grease thing. Last time I did it wrong and Ramon redid all of it in front of everybody. So I just leave.\"","choices":[{"id":"teach-it","text":"Say, \"That is fixable. Come to the wash line tonight, I will run the three pots with you, then you have got it.\"","deltas":{"delegation":3,"communication":2,"conflict_resolution":2},"coaching":{"text":"This is the whole EDGE sequence in one move — you explain it, do the first pot with him, then let him run the rest. An avoidance problem was really a skill problem.","edge_stage":"demonstrate","principle":"Avoidance is often missing skill"},"next":"good-landing"},{"id":"talk-to-ramon","text":"Say, \"I will talk to Ramon about redoing people''s work in front of everyone.\" Leave the dishes part for later.","deltas":{"conflict_resolution":2,"communication":1,"delegation":-1},"coaching":{"text":"You caught the half of this that Cole could not fix himself, and that matters. Cole still does not know how to degrease a pot, so tonight is likely a repeat.","principle":"Fix both halves"},"next":"soft-landing"},{"id":"minimize","text":"Say, \"Nobody cares about that. Just do the job.\"","deltas":{"conflict_resolution":-3,"communication":-2},"coaching":{"text":"He told you the real reason, which is the hard part, and you told him it did not count. He will not tell you the real reason next time.","principle":"Do not punish honesty"},"next":"rough-landing"}]},"reassign-fallout":{"id":"reassign-fallout","type":"decision","prompt":"You quietly swap the roster. Ramon sees it, looks at you, and does not say anything. Cole notices too and does not say anything either.","choices":[{"id":"course-correct","text":"Put the roster back and go find Cole before dinner.","deltas":{"conflict_resolution":2,"initiative":2},"coaching":{"text":"Backing out of a bad call the same day costs almost nothing. Letting it stand all weekend costs you the scout who was covering.","principle":"Reverse small mistakes fast"},"next":"aside-opening"},{"id":"leave-it","text":"Leave it. It is one more night and then everyone goes home.","deltas":{"conflict_resolution":-2,"delegation":-2,"initiative":-2},"coaching":{"text":"It is never one more night. Next campout the roster is the same, the pattern is established, and Ramon has stopped volunteering.","principle":"Patterns outlive weekends"},"next":"rough-landing"}]},"good-landing":{"id":"good-landing","type":"outcome","prompt":"Cole does pots that night with you standing there for the first one. He does the other two on his own, badly at first, then fine. Ramon leaves it alone.","debrief":"A scout who keeps ducking a job is usually avoiding something specific — not knowing how, or being embarrassed in front of the patrol. You only find that out by asking and then not filling the silence.","edge_focus":"demonstrate"},"soft-landing":{"id":"soft-landing","type":"outcome","prompt":"Cole shows up for cleanup, hangs back, and does about half of it. Nobody says anything about it.","debrief":"Half-addressing something buys you one quiet night. The scouts who covered for him are keeping a tally even when they stop mentioning it."},"rough-landing":{"id":"rough-landing","type":"outcome","prompt":"Cole does not come to cleanup. Ramon does the pots, slowly, making sure you can see him doing it.","debrief":"Nothing here was unrecoverable. The cost was not the pots — it was that two scouts now believe the roster only applies to whoever cannot get out of it."}}}'::jsonb
  ),
  (
    'grubmaster-empty-handed',
    'training'::public.scenario_kind,
    'Grubmaster, Empty-Handed',
    'Your grubmaster shows up at departure with no food.',
    'Friday 5:40 pm, church parking lot, trucks loading',
    array['PL', 'APL']::public.leadership_role[],
    array['second_class', 'first_class', 'star', 'life']::public.scout_rank[],
    array['planning', 'delegation']::text[],
    4,
    '{"version":1,"root":"arrival","nodes":{"arrival":{"id":"arrival","type":"decision","prompt":"Departure is in twenty minutes. Nathan volunteered to be grubmaster two weeks ago. He just walked up with a backpack and nothing else. \"My mom said we would do it after school and then she had to work.\"","choices":[{"id":"blow-up","text":"Say, \"Are you serious? You had two weeks,\" in front of the loading crew.","deltas":{"conflict_resolution":-2,"communication":-1},"coaching":{"text":"Twenty minutes before departure is the worst possible time to spend on who is at fault. Nothing you say right now buys food.","principle":"Fix first, review later"},"next":"triage"},{"id":"triage-now","text":"Say, \"Okay. Tell me what we do have,\" and start counting what is already in the patrol box.","deltas":{"planning":3,"initiative":2},"coaching":{"text":"You moved straight to the only question that matters before the trucks leave. Knowing what is actually in the box is the difference between one problem and a weekend of them.","principle":"Inventory before decisions"},"next":"triage"},{"id":"tell-adult","text":"Go tell the Scoutmaster the patrol has no food and ask what to do.","deltas":{"initiative":-2,"planning":-1,"communication":1},"coaching":{"text":"You will need to tell an adult — someone is driving to a store. Leading with \"what do we do\" instead of \"here is our plan, we need a driver\" hands your patrol''s problem to an adult.","principle":"Bring a plan, not just a problem"},"next":"triage"}]},"triage":{"id":"triage","type":"decision","prompt":"The patrol box has a bag of rice, two cans of chili, oatmeal packets, and a half bottle of oil. That is one dinner and a thin breakfast for six scouts, for a two-night campout. There is a grocery store four minutes from the campground.","choices":[{"id":"nathan-owns-it","text":"Tell Nathan: \"You are still grubmaster. Write a list for two dinners and two breakfasts on the drive. We stop at the store on the way in — I will ask Mr. Alvarez.\"","deltas":{"delegation":3,"planning":2,"communication":2},"coaching":{"text":"Leaving the job with the scout who dropped it is the harder call and the right one — you replaced the failure with a chance to fix it. You handled the part he cannot, which is getting an adult and a vehicle.","edge_stage":"enable","principle":"Let people recover their own job"},"next":"store-stop"},{"id":"take-it-over","text":"Take the menu yourself. Nathan clearly cannot handle it.","deltas":{"delegation":-3,"planning":1},"coaching":{"text":"The weekend gets fed and Nathan learns that dropping a job means someone else picks it up. You have also added grubmaster to everything else you are doing this weekend.","principle":"Rescuing teaches the wrong lesson"},"next":"store-stop"},{"id":"stretch-it","text":"Skip the store. Stretch what is in the box and make it work.","deltas":{"planning":-2,"initiative":1},"coaching":{"text":"Six scouts on rice and oatmeal for two days is not toughness, it is a planning failure with extra steps. Cold, hungry scouts make worse decisions on Saturday.","principle":"Do not make scouts pay for a fixable gap"},"next":"lean-weekend"}]},"store-stop":{"id":"store-stop","type":"decision","prompt":"The store stop works. Bags are in the truck and the patrol is setting up by dark. Sunday afternoon, gear is unloaded and Nathan is standing around waiting to see if you are going to say something.","choices":[{"id":"no-debrief","text":"Say nothing. It worked out and the weekend was fine.","deltas":{"communication":-2,"planning":-1},"coaching":{"text":"Skipping the conversation means the only lesson available is \"it worked out\". The next grubmaster job will go the same way.","principle":"The debrief is where it sticks"},"next":"lean-weekend"},{"id":"fix-the-system","text":"Say, \"That was close. Next time the menu is due at the Tuesday meeting, not Friday — I will ask you for it then.\" ","deltas":{"planning":3,"delegation":2,"communication":2},"coaching":{"text":"You changed the deadline instead of just changing your opinion of Nathan. A checkpoint three days early turns a disaster into a small fixable miss.","edge_stage":"explain","principle":"Move the deadline forward"},"next":"solid-weekend"},{"id":"blame-debrief","text":"Say, \"You almost wrecked the campout for everybody.\"","deltas":{"conflict_resolution":-2,"communication":-1},"coaching":{"text":"He knows. Saying it out loud on Sunday costs you the chance that he volunteers for anything again.","principle":"Say the thing that changes next time"},"next":"lean-weekend"}]},"lean-weekend":{"id":"lean-weekend","type":"outcome","prompt":"The patrol eats thin, complains about it Saturday, and nobody volunteers for grubmaster at the next meeting.","debrief":"The food was recoverable in about fifteen minutes. What is harder to recover is a patrol that has learned volunteering for a job is how you end up blamed."},"solid-weekend":{"id":"solid-weekend","type":"outcome","prompt":"Nathan brings a menu to the Tuesday meeting before you ask for it. It is not a great menu, but it is two weeks early.","debrief":"Most dropped jobs are not attitude problems — they are deadline problems. Moving the checkpoint earlier gives you room to catch it while it is still small.","edge_focus":"enable"}}}'::jsonb
  ),
  (
    'two-scouts-one-story',
    'training'::public.scenario_kind,
    'Two Scouts, One Story',
    'Two scouts give you completely different accounts of the same thing.',
    'Saturday afternoon, summer camp campsite',
    array['PL', 'APL', 'SPL']::public.leadership_role[],
    array['first_class', 'star', 'life', 'eagle']::public.scout_rank[],
    array['conflict_resolution', 'communication']::text[],
    4,
    '{"version":1,"root":"report","nodes":{"report":{"id":"report","type":"decision","prompt":"Devin tells you that Sam went through his pack and took his knife. Sam says Devin lent it to him Thursday and is now \"making it a thing\". They are both certain, both loud, and both looking at you.","choices":[{"id":"pick-a-side","text":"Decide who you believe based on what you know about each of them.","deltas":{"conflict_resolution":-3},"coaching":{"text":"Deciding on reputation means the scout with the better standing wins every dispute, which is exactly how a patrol stops bringing you things. You have not asked a single question yet.","principle":"Never rule on reputation"},"next":"ruling-fallout"},{"id":"both-separately","text":"Separate them. Talk to each one alone and ask for the whole sequence — where, when, who else was around.","deltas":{"conflict_resolution":3,"communication":2},"coaching":{"text":"Detail is what tells two honest misunderstandings apart from one scout covering. Asking for the sequence rather than \"what happened\" gets you facts that can be checked.","principle":"Ask for the sequence"},"next":"details-emerge"},{"id":"make-them-shake","text":"Tell them both to drop it and shake hands.","deltas":{"conflict_resolution":-1,"communication":-1},"coaching":{"text":"A forced handshake ends the noise in front of you and nothing else. Whichever one is actually right now believes that being right does not matter.","principle":"Quiet is not resolved"},"next":"ruling-fallout"}]},"details-emerge":{"id":"details-emerge","type":"decision","prompt":"Alone, Devin says he lent Sam a different knife back in the spring and never got it back, and today he saw his own knife in Sam''s hand. Sam, alone, says Devin handed it to him at the trading post Thursday and that Devin does this. Neither one has a witness.","choices":[{"id":"declare-verdict","text":"Decide Sam is lying and tell him to give it back.","deltas":{"conflict_resolution":-2,"communication":-1},"coaching":{"text":"You do not have enough to decide, and guessing at a verdict is how you end up wrong in front of everyone. There is a version of this where both of them believe what they are saying.","principle":"Do not rule on a coin flip"},"next":"ruling-fallout"},{"id":"fix-forward","text":"Bring them together and say, \"I cannot prove what happened Thursday. Here is what we do from here: the knife goes back to Devin, and nobody in this patrol borrows gear without the owner saying it out loud in front of someone else.\"","deltas":{"conflict_resolution":3,"communication":3,"planning":1},"coaching":{"text":"Being straight that you cannot establish the past is more credible than a guess, and it lets you spend your authority on the rule instead of the verdict. The new rule prevents the next one.","edge_stage":"explain","principle":"Rule on the future, not the past"},"next":"workable-peace"},{"id":"escalate","text":"Take it to the Scoutmaster — a knife and an accusation of stealing is above you.","deltas":{"conflict_resolution":1,"communication":1},"coaching":{"text":"A theft accusation at camp is a reasonable thing to loop an adult into, and you are not wrong to. Go in with what each scout said and what you have already ruled out, so the adult is adding judgement rather than starting over.","principle":"Escalate with your work attached"},"next":"adult-involved"}]},"ruling-fallout":{"id":"ruling-fallout","type":"decision","prompt":"Whichever way you called it, the scout on the losing end has stopped talking to you. By dinner the patrol has quietly picked sides and two scouts are eating apart from everyone.","choices":[{"id":"go-back","text":"Go back to the scout you ruled against, tell him you called it too fast, and ask him to walk you through it again.","deltas":{"conflict_resolution":3,"communication":2,"initiative":2},"coaching":{"text":"Saying you got ahead of yourself costs less standing than defending a call you are not sure of. Scouts extend a lot of credit to a leader who reopens something.","principle":"You are allowed to reopen it"},"next":"workable-peace"},{"id":"hold-the-line","text":"Hold the call. Reversing it would make you look like you can be pushed around.","deltas":{"conflict_resolution":-2,"communication":-1},"coaching":{"text":"Consistency is worth something, but not when what you are being consistent about is a guess. The patrol reads it as \"he decides and then defends it\", which is not the same as fair.","principle":"Firm is not the same as right"},"next":"cold-patrol"}]},"workable-peace":{"id":"workable-peace","type":"outcome","prompt":"Neither scout is happy. Both accept it. The gear rule holds for the rest of the week, and by Wednesday they are on the same volleyball team without discussing it.","debrief":"Most peer disputes cannot be proved, and trying to is the trap. You get further by being honest about what you do not know and being specific about what happens next.","edge_focus":"explain"},"adult-involved":{"id":"adult-involved","type":"outcome","prompt":"The Scoutmaster talks to both scouts and to a camp staffer who was at the trading post Thursday. It gets sorted out that afternoon.","debrief":"Bringing in an adult is not losing. Doing it with your own work attached is what separates escalating from handing it off."},"cold-patrol":{"id":"cold-patrol","type":"outcome","prompt":"The split holds through the week. Nobody brings you anything else, including two things you would have wanted to know about.","debrief":"The real cost of a bad ruling is not that one scout is upset. It is that the patrol stops telling you things early, while they are still small."}}}'::jsonb
  ),
  (
    'frozen-out',
    'training'::public.scenario_kind,
    'Frozen Out',
    'A scout who transferred into your patrol is being left out of everything.',
    'Third troop meeting since the patrol reshuffle',
    array['PL', 'APL']::public.leadership_role[],
    array['second_class', 'first_class', 'star', 'life']::public.scout_rank[],
    array['conflict_resolution', 'communication']::text[],
    4,
    '{"version":1,"root":"pattern","nodes":{"pattern":{"id":"pattern","type":"decision","prompt":"Owen moved into your patrol when the troop reorganised. Nobody is mean to him. He just never gets picked, never gets asked, and when the patrol jokes about last year he has nothing to say. Tonight he sat one chair outside the circle for the whole meeting and nobody moved over.","choices":[{"id":"lecture-patrol","text":"Tell the patrol they need to include Owen and that it is not Scoutlike to leave someone out.","deltas":{"communication":-1,"conflict_resolution":-1},"coaching":{"text":"You are right on the substance, and a lecture makes Owen the kid who needed the PL to make people be nice to him. That is worse for him than where he started.","principle":"Do not make him the project"},"next":"after-lecture"},{"id":"ask-owen","text":"Catch Owen on the way out and ask him how it is going in the patrol.","deltas":{"communication":3,"conflict_resolution":1},"coaching":{"text":"Asking him first means you find out whether he is unhappy or just quiet, which changes what you should do. He may also tell you something specific you had not seen.","principle":"Ask before you fix"},"next":"owens-answer"},{"id":"structural-fix","text":"Say nothing to anyone. Put Owen and two others on a job together for the campout and let it work itself out.","deltas":{"delegation":2,"planning":2,"communication":-1},"coaching":{"text":"Shared work builds more than announcements do, so the instinct is good. Doing it without ever asking Owen means you are guessing at what the problem is.","principle":"Shared work beats announcements"},"next":"campout-test"}]},"owens-answer":{"id":"owens-answer","type":"decision","prompt":"Owen shrugs. \"It is fine.\" Then, after a second: \"I mean, I do not really know anybody. At my old patrol I was the one who did the fire.\" He says it like he is not asking for anything.","choices":[{"id":"give-him-the-fire","text":"Say, \"Then you are on fire and cooking for the campout. Take Miles with you — he has never lit one without help.\"","deltas":{"delegation":3,"communication":2,"initiative":2},"coaching":{"text":"He told you exactly what he brings, and you gave him a role where the patrol has to interact with him to eat. Pairing him with someone who needs teaching turns him into the person who knows something.","edge_stage":"enable","principle":"Give the new scout a reason to be needed"},"next":"campout-test"},{"id":"reassure","text":"Say, \"Give it time, you will fit in,\" and leave it.","deltas":{"communication":-2,"initiative":-2},"coaching":{"text":"He will fit in eventually or he will quit, and nothing you did affects which. He gave you a concrete thing he can do and you handed it back.","principle":"Time is not a plan"},"next":"slow-fade"},{"id":"tell-others-quietly","text":"Quietly ask two scouts in the patrol to pull him in without telling him you did.","deltas":{"conflict_resolution":2,"communication":1,"delegation":1},"coaching":{"text":"Working through two scouts rather than announcing it to the patrol keeps his standing intact. It depends entirely on picking the right two.","principle":"Work through individuals"},"next":"campout-test"}]},"after-lecture":{"id":"after-lecture","type":"decision","prompt":"The patrol nods through it. For about ten minutes people make a point of including Owen in a way that is obvious to everyone including Owen. Then it goes back to normal.","choices":[{"id":"now-ask-owen","text":"Find Owen after and ask him directly how it is going.","deltas":{"communication":2,"conflict_resolution":1,"initiative":1},"coaching":{"text":"Following an announcement with an actual conversation recovers most of it. Ask about the patrol rather than about the speech.","principle":"Follow the announcement with a conversation"},"next":"owens-answer"},{"id":"call-it-done","text":"Consider it handled. You said something and they agreed.","deltas":{"conflict_resolution":-2,"communication":-1},"coaching":{"text":"Agreement in a meeting is free. Nothing about how the patrol actually spends time changed, which is where the problem lives.","principle":"Agreement is not change"},"next":"slow-fade"}]},"campout-test":{"id":"campout-test","type":"outcome","prompt":"On the campout Owen runs the fire, shows Miles how to build it, and burns the first batch of bacon badly enough that it becomes a patrol joke. He is in the joke rather than outside it.","debrief":"Belonging in a patrol comes from doing something the patrol needs, not from being told to be nicer. Your job was to find the thing he could own and hand it to him.","edge_focus":"enable"},"slow-fade":{"id":"slow-fade","type":"outcome","prompt":"Owen comes to the next two meetings, misses the campout, and then stops showing up. Nobody in the patrol mentions it.","debrief":"Scouts rarely quit over one thing. They quit over a few months of no particular reason to be there, which is a problem a patrol leader is actually positioned to see coming."}}}'::jsonb
  ),
  (
    'meeting-segment',
    'training'::public.scenario_kind,
    'Your Fifteen Minutes',
    'You have a meeting segment to run and eleven minutes to plan it.',
    'Tuesday, fifteen minutes before the troop meeting',
    array['PL', 'APL', 'SPL']::public.leadership_role[],
    array['tenderfoot', 'second_class', 'first_class', 'star']::public.scout_rank[],
    array['planning', 'communication']::text[],
    4,
    '{"version":1,"root":"assigned","nodes":{"assigned":{"id":"assigned","type":"decision","prompt":"The SPL gave your patrol fifteen minutes of tonight''s meeting for a skill session on knots. Four of your six scouts need the two half-hitches for rank. Two already have it. You have eleven minutes before the meeting starts and no rope out yet.","choices":[{"id":"wing-it","text":"You know the knot. Get the rope out and figure out the rest when you are up there.","deltas":{"planning":-3,"initiative":1},"coaching":{"text":"Knowing a knot and teaching a knot to six scouts of different levels are different jobs. Fifteen unplanned minutes becomes five minutes of demo and ten of scouts hitting each other with rope.","principle":"Knowing it is not a lesson plan"},"next":"the-session"},{"id":"edge-plan","text":"Sketch it: two minutes explaining where the knot gets used, two demonstrating slowly, seven with everyone on their own rope while you circle, last two everyone ties it without looking at you.","deltas":{"planning":3,"communication":2},"coaching":{"text":"That is EDGE with a clock on it — and the clock is the part people skip. Ending with everyone tying it unaided is how you find out if it landed.","edge_stage":"guide","principle":"Put a clock on each stage"},"next":"the-session"},{"id":"use-the-two","text":"Grab the two scouts who already know it and tell them each to take two of the others. You float.","deltas":{"delegation":3,"planning":2},"coaching":{"text":"Two-on-one beats six-on-one for anything with hands, and the scouts teaching it learn it better than they knew it. Give them thirty seconds of direction first so they do not each teach a different knot.","edge_stage":"enable","principle":"The best teacher just learned it"},"next":"the-session"}]},"the-session":{"id":"the-session","type":"decision","prompt":"Six minutes in. Two scouts have it. Two are close. One is tying a granny knot with total confidence, and one has put his rope down and is talking to someone in the next patrol.","choices":[{"id":"restart-for-all","text":"Stop everyone and demonstrate the whole thing again from the front.","deltas":{"communication":-1,"planning":-1},"coaching":{"text":"You have just taken the two scouts who had it and given them four minutes of nothing to do. A repeat from the front is the most expensive way to reach two scouts.","principle":"Do not reteach the room for two"},"next":"mixed-result"},{"id":"pair-and-redirect","text":"Pair each scout who has it with one who does not, and go sit next to the scout with the granny knot yourself.","deltas":{"delegation":3,"communication":2,"planning":1},"coaching":{"text":"Everyone has something to do and the hardest case gets the person with the most skill, which is you. The scout who drifted off is usually the one who cannot do it and does not want that visible.","edge_stage":"guide","principle":"Split the room by what they need"},"next":"landed"},{"id":"push-through","text":"Keep going and finish on time. Most of them have it.","deltas":{"planning":1,"communication":-2},"coaching":{"text":"Finishing on time is worth something and the two scouts who needed it are the two who came for it. \"Most of them\" was not the point of the session.","principle":"On time is not the same as done"},"next":"mixed-result"}]},"landed":{"id":"landed","type":"outcome","prompt":"At fourteen minutes everyone ties it once, unaided, while you watch. The granny-knot scout gets it on his third try and looks around to see if anyone noticed.","debrief":"A skill session is not done when you have explained it — it is done when you have watched each scout do it. That last check is what turns a demo into a sign-off.","edge_focus":"enable"},"mixed-result":{"id":"mixed-result","type":"outcome","prompt":"The segment ends on time. Four scouts can tie it, two cannot, and both of those two needed it for rank.","debrief":"Fifteen minutes is enough to teach two half-hitches to six scouts if the plan splits them by what they already know. Running one lesson at the whole room is what makes it not enough."}}}'::jsonb
  ),
  (
    'totin-chip-call',
    'training'::public.scenario_kind,
    'The Hatchet',
    'A younger scout is using a hatchet in a way that is about to hurt someone.',
    'Saturday morning, patrol wood pile',
    array['PL', 'APL', 'SPL']::public.leadership_role[],
    array['first_class', 'star', 'life', 'eagle']::public.scout_rank[],
    array['initiative', 'communication']::text[],
    3,
    '{"version":1,"root":"the-swing","nodes":{"the-swing":{"id":"the-swing","type":"decision","prompt":"Kai is eleven, earned his Totin'' Chip three weeks ago, and is splitting kindling with a hatchet. He is holding the piece upright with his free hand and swinging down at it. Another scout is standing about two feet to his left watching. Nobody has been hurt yet.","choices":[{"id":"stop-now","text":"Say \"Kai, stop\" loud enough to be heard, and walk over.","deltas":{"initiative":3,"communication":2},"coaching":{"text":"Unsafe tool use is the one place where stopping it first and being polite second is correct. The blood circle and the hand placement are both wrong, and you do not have time to phrase it well.","principle":"Safety interrupts everything"},"next":"after-stop"},{"id":"wait-for-pause","text":"Wait until he finishes the piece, then bring it up so you do not startle him mid-swing.","deltas":{"initiative":-2,"communication":1},"coaching":{"text":"Not startling someone holding an axe is a real consideration — say his name rather than shouting from behind. Waiting for the piece to finish is waiting for the swing that lands on his hand.","principle":"Do not wait out an unsafe swing"},"next":"after-stop"},{"id":"find-adult","text":"Go find an adult leader and let them handle a tool safety issue.","deltas":{"initiative":-3},"coaching":{"text":"The adult is thirty seconds away and the hatchet is swinging now. A scout with a Totin'' Chip can be corrected by any scout — that is the point of the card.","principle":"Distance is the deciding factor"},"next":"near-miss"}]},"after-stop":{"id":"after-stop","type":"decision","prompt":"Kai stops and looks up, embarrassed, with three other scouts now watching. The hatchet is down.","choices":[{"id":"corner-the-chip","text":"Cut a corner off his Totin'' Chip on the spot. That is what it is for.","deltas":{"conflict_resolution":-2,"communication":-1},"coaching":{"text":"Corners are real and sometimes correct, and using one as the first move in front of an audience spends a lot for a first mistake. Ask yourself whether he does not care or was never actually taught.","principle":"Ask whether it is attitude or training"},"next":"chip-cut"},{"id":"show-him","text":"Say, \"Your hand is inside the swing.\" Show him the contact method with a stick and a batoning piece, then watch him do three.","deltas":{"communication":3,"initiative":2,"delegation":1},"coaching":{"text":"Naming the specific error, showing the alternative, then watching him do it is the whole correction in about ninety seconds. The scouts watching just got the lesson too.","edge_stage":"demonstrate","principle":"Correct with a replacement, not a rule"},"next":"taught"},{"id":"vague-warning","text":"Say, \"Be careful with that,\" and go back to what you were doing.","deltas":{"communication":-2,"initiative":-1},"coaching":{"text":"\"Be careful\" tells him to keep doing what he is doing with more tension in his shoulders. He does not know which part was wrong.","principle":"Name the specific error"},"next":"near-miss"}]},"taught":{"id":"taught","type":"outcome","prompt":"Kai splits the rest of the pile with his hand out of the way. Twenty minutes later you see him telling another scout to move out of the blood circle.","debrief":"Safety corrections stick when they come with a replacement technique and a few reps under supervision. A rule alone leaves the scout with nothing to do differently.","edge_focus":"demonstrate"},"chip-cut":{"id":"chip-cut","type":"outcome","prompt":"Kai hands over the card with a corner gone and does not touch a tool for the rest of the weekend. He also does not learn the right way to do it.","debrief":"The Totin'' Chip has corners for a reason and cutting one is sometimes exactly right. It works as a consequence for a scout who knows better, not as a substitute for teaching one who does not."},"near-miss":{"id":"near-miss","type":"outcome","prompt":"The hatchet glances off a knot and buries in the dirt two inches from his shoe. Everyone stops. Nobody is hurt.","debrief":"This one landed in the dirt. The gap between a near miss and a trip to the emergency room at camp is usually a few inches and not much else."}}}'::jsonb
  ),
  (
    'apl-steps-in',
    'training'::public.scenario_kind,
    'You Are Up',
    'Your PL is out sick and the campout leaves in two hours.',
    'Friday afternoon, text message from your PL',
    array['APL', 'PL']::public.leadership_role[],
    array['second_class', 'first_class', 'star', 'life']::public.scout_rank[],
    array['initiative', 'delegation']::text[],
    4,
    '{"version":1,"root":"the-text","nodes":{"the-text":{"id":"the-text","type":"decision","prompt":"Your PL texts you at 3 pm: \"Got strep, not coming. Sorry.\" Departure is 5:30. You do not know who has the patrol box, whether the menu got shopped, or what the patrol signed up to do at the camporee tomorrow.","choices":[{"id":"show-up-and-see","text":"Show up at 5:30 and sort it out in the parking lot with everyone there.","deltas":{"initiative":-2,"planning":-2},"coaching":{"text":"You have two and a half hours that are worth more than the twenty minutes you will have in the lot. Everything you can find out now is something you are not improvising in front of the patrol.","principle":"Use the time you have now"},"next":"the-lot"},{"id":"three-texts","text":"Send three texts right now: one to the patrol asking who has the box and the food, one to the PL asking what he already set up, one to the SPL saying you are covering.","deltas":{"initiative":3,"communication":3,"planning":2},"coaching":{"text":"Three short messages in the right direction close most of the unknowns before you leave the house. Telling the SPL matters because he is now planning around a patrol with a different leader.","principle":"Close the unknowns early"},"next":"the-lot"},{"id":"ask-spl-to-lead","text":"Text the SPL and ask him to run your patrol this weekend since the PL is out.","deltas":{"initiative":-3,"delegation":-1},"coaching":{"text":"This is the job. Assistant Patrol Leader means you are the patrol leader when the patrol leader is not there, and handing it up is the one move that is clearly not in the role.","principle":"Backing up is the whole job"},"next":"the-lot"}]},"the-lot":{"id":"the-lot","type":"decision","prompt":"In the parking lot: the patrol box is there, the food is not, and two scouts assumed the campout was cancelled when they heard the PL was sick. One of them, Wes, is a year older than you and has been PL before.","choices":[{"id":"announce-authority","text":"Open with, \"The PL is out so I am in charge this weekend, and I need everyone to listen.\"","deltas":{"communication":-2,"conflict_resolution":-1},"coaching":{"text":"Announcing that you are in charge is what people do when they are not sure they are. Giving out the first useful instruction establishes it faster than claiming it.","principle":"Authority comes from the first instruction"},"next":"wes-question"},{"id":"assign-and-move","text":"Say, \"Wes, take two guys and do the food run with Mr. Reyes — here is the menu. Everyone else, gear in the truck.\"","deltas":{"delegation":3,"initiative":2,"communication":2},"coaching":{"text":"Giving the older scout the biggest job is a stronger move than trying to keep him small. Everyone is doing something inside ninety seconds, which is what settles a parking lot.","edge_stage":"enable","principle":"Give the strongest scout the real job"},"next":"wes-question"},{"id":"defer-to-wes","text":"Tell Wes he should probably run the weekend since he has done it before.","deltas":{"initiative":-3,"delegation":1},"coaching":{"text":"Handing the role to whoever is oldest undoes the point of having an APL. Use his experience — asking him what he would do is different from giving him the job.","principle":"Use experience without surrendering the role"},"next":"wes-question"}]},"wes-question":{"id":"wes-question","type":"decision","prompt":"Saturday morning, in front of the patrol, Wes says, \"We should skip the first camporee event and do our own thing. It is going to be boring.\" Four scouts look at you. He is probably right that it will be boring.","choices":[{"id":"cave","text":"Go with it. He knows the camporee better than you do.","deltas":{"initiative":-2,"conflict_resolution":-1},"coaching":{"text":"Your patrol signed up and the event count affects the troop. Changing the plan because the loudest scout finds it boring is the decision you will be asked about later.","principle":"Boring is not a reason"},"next":"loose-weekend"},{"id":"hold-with-reason","text":"Say, \"We signed up, so we are going. If it is bad after twenty minutes, come find me and we will figure out the afternoon.\"","deltas":{"initiative":3,"communication":3,"conflict_resolution":2},"coaching":{"text":"You held the commitment and gave him a real path to be heard, which is what keeps a strong scout working with you rather than against you. The twenty-minute window costs you nothing.","principle":"Hold the line, leave a door"},"next":"solid-weekend"},{"id":"shut-down","text":"Say, \"I am in charge, we are going,\" and end it.","deltas":{"conflict_resolution":-2,"initiative":1},"coaching":{"text":"You got the right outcome and paid more for it than you needed to. \"We signed up\" is a reason the patrol can accept; \"I am in charge\" is one they can only comply with.","principle":"Reasons travel further than rank"},"next":"solid-weekend"}]},"solid-weekend":{"id":"solid-weekend","type":"outcome","prompt":"The patrol does the event, places fourth, and complains about it cheerfully all afternoon. On Sunday the SPL asks you who ran the patrol, because it looked like it ran fine.","debrief":"Covering for a PL is not a lesser version of the job. Most of it is closing unknowns early and giving the first clear instruction before anyone else fills the gap.","edge_focus":"enable"},"loose-weekend":{"id":"loose-weekend","type":"outcome","prompt":"The patrol skips the event, the troop is short a patrol in the standings, and the SPL asks you about it Sunday in front of the other leaders.","debrief":"The weekend was survivable. What it cost was the answer to \"can this patrol run without its PL\", and that answer follows you into the next position."}}}'::jsonb
  ),
  (
    'homesick-first-night',
    'training'::public.scenario_kind,
    'First Night at Camp',
    'An eleven-year-old is crying behind the tents and does not want anyone to know.',
    'Sunday night, first night of summer camp',
    array['APL', 'PL', 'SPL']::public.leadership_role[],
    array['first_class', 'star', 'life', 'eagle']::public.scout_rank[],
    array['communication', 'initiative']::text[],
    4,
    '{"version":1,"root":"find-him","nodes":{"find-him":{"id":"find-him","type":"decision","prompt":"It is about 9:40. You go behind the tent line to get something out of your pack and find Elias sitting against a tree, crying, phone in his hand. He sees you and wipes his face fast. This is his first week away from home.","choices":[{"id":"back-away","text":"Back off and pretend you did not see. He clearly does not want anyone to know.","deltas":{"initiative":-3,"communication":-1},"coaching":{"text":"He does not want the patrol to know, which is not the same as wanting to be alone. Leaving now confirms to him that it is the kind of thing people walk away from.","principle":"Private is not the same as alone"},"next":"morning-after"},{"id":"sit-down","text":"Sit down a few feet away without saying much, and wait.","deltas":{"communication":3,"initiative":2},"coaching":{"text":"Sitting rather than standing over him drops the pressure, and not talking first means he is not being interrogated at the worst moment of his day. This is usually the fastest way in.","principle":"Sit down and wait"},"next":"he-talks"},{"id":"cheer-up","text":"Say, \"Hey, you are fine, it is only a week — tomorrow is the climbing tower, it is awesome.\"","deltas":{"communication":-2,"initiative":1},"coaching":{"text":"You noticed and you engaged, which beats walking away. Telling an upset eleven-year-old that he is fine mostly teaches him not to mention it again.","principle":"Do not argue with how he feels"},"next":"he-talks"},{"id":"straight-to-adult","text":"Go get the Scoutmaster right away — homesickness is an adult issue.","deltas":{"initiative":-1,"communication":1},"coaching":{"text":"Adults do need to know at some point tonight, especially if he is asking to go home. Leading with it means his first experience of being upset at camp is being reported.","principle":"Loop adults in, do not open with them"},"next":"morning-after"}]},"he-talks":{"id":"he-talks","type":"decision","prompt":"After a while he says, \"I texted my mom to come get me. She said to ask you guys.\" He is not being dramatic about it. He just wants to go home.","choices":[{"id":"one-day-deal","text":"Say, \"Okay. Do one day. Tomorrow night if you still want to go, I will walk you to the Scoutmaster myself and I will not make it weird.\"","deltas":{"communication":3,"conflict_resolution":2,"initiative":2},"coaching":{"text":"A short commitment he can actually see the end of beats \"give it a week\", and promising to help him leave means you are on his side rather than blocking him. Most homesickness breaks inside forty-eight hours once there is something to do.","principle":"Shrink the commitment"},"next":"tuesday"},{"id":"talk-him-out","text":"Tell him nobody goes home from camp and he will regret it.","deltas":{"communication":-2,"conflict_resolution":-1},"coaching":{"text":"He might regret it, and that is not an argument that reaches a homesick eleven-year-old at 9:40 pm. You have also told him the answer is no from the one person he was willing to talk to.","principle":"Do not close the only open door"},"next":"morning-after"},{"id":"get-adult-with-him","text":"Say, \"That is a real thing and it is not mine to decide. Come with me and we will tell Mr. Boyd together — I will stay with you.\"","deltas":{"communication":2,"initiative":2},"coaching":{"text":"A scout asking to leave camp is genuinely an adult decision and you are right to move it there. Walking in with him instead of sending him is what keeps it from feeling like being turned in.","principle":"Walk them in, do not send them"},"next":"tuesday"}]},"tuesday":{"id":"tuesday","type":"outcome","prompt":"Elias stays. Monday is rough. By Tuesday he has a partner in swimming class and has stopped checking his phone at dinner. On Friday he asks whether the troop does winter camp.","debrief":"Homesickness is not solved by arguing about it. It is solved by a short horizon, something to do tomorrow, and one person who noticed without making it public.","edge_focus":"guide"},"morning-after":{"id":"morning-after","type":"outcome","prompt":"Elias goes home Monday afternoon. He does not come back in the fall, and the troop loses a scout it never really had.","debrief":"Sometimes a scout goes home and that is the right call. The part worth looking at is whether anyone sat down with him before the decision got made for him."}}}'::jsonb
  ),
  (
    'plc-report-back',
    'training'::public.scenario_kind,
    'Reporting Back',
    'You went to the PLC for your PL and now have to bring it back to the patrol.',
    'Right after the PLC, before the troop meeting starts',
    array['APL', 'PL']::public.leadership_role[],
    array['second_class', 'first_class', 'star', 'life']::public.scout_rank[],
    array['communication', 'planning']::text[],
    3,
    '{"version":1,"root":"walk-out","nodes":{"walk-out":{"id":"walk-out","type":"decision","prompt":"You sat in on the PLC in your PL''s place. Four things got decided: the November campout moved to the 14th, each patrol owes a meeting segment, dues are going up five dollars, and the troop needs two scouts for a service project on the 8th. You have about four minutes before the meeting starts.","choices":[{"id":"tell-pl-only","text":"Send it all to your PL and let him tell the patrol next week.","deltas":{"communication":-2,"initiative":-1},"coaching":{"text":"By next week the service project is three days out and nobody has signed up. Information that has a date on it does not keep.","principle":"Dated information does not keep"},"next":"next-week"},{"id":"dump-it-all","text":"Read all four items to the patrol in the next four minutes.","deltas":{"communication":1,"planning":-1},"coaching":{"text":"Everything got said, which is better than nothing getting said. Four items in four minutes to a patrol that is half paying attention means they will remember roughly one.","principle":"Four items is three too many"},"next":"next-week"},{"id":"lead-with-action","text":"Lead with the two things that need something from them tonight — the service project sign-up and who takes the meeting segment — and send the date and dues in the group chat after.","deltas":{"communication":3,"planning":3},"coaching":{"text":"Sorting by what needs a decision tonight versus what just needs to be known is most of good reporting. The chat handles the reference material without spending the patrol''s attention on it.","principle":"Separate decisions from announcements"},"next":"good-handoff"}]},"good-handoff":{"id":"good-handoff","type":"decision","prompt":"You get two volunteers for the service project inside a minute. For the meeting segment, nobody moves — the patrol has been assigned this three times and it has landed on the same two scouts every time.","choices":[{"id":"same-two","text":"Ask the same two. They are reliable and it is easier.","deltas":{"delegation":-2,"communication":-1},"coaching":{"text":"Reliable scouts get used until they are done being reliable. Three in a row is where a patrol starts sorting itself into the ones who do things and the ones who do not.","principle":"Rotate before you burn them"},"next":"next-week"},{"id":"pair-new-with-old","text":"Pair one of the two reliable scouts with someone who has never run a segment, and tell the experienced one his job is to let the other one talk.","deltas":{"delegation":3,"communication":2,"initiative":1},"coaching":{"text":"This is the enable step done deliberately — the experienced scout is there as a backstop, not a presenter. It is also how the pool of scouts who can run a segment gets bigger.","edge_stage":"enable","principle":"Pair to widen the pool"},"next":"good-handoff-end"}]},"good-handoff-end":{"id":"good-handoff-end","type":"outcome","prompt":"Two scouts run the segment next week. It is rough in the middle and finishes fine. The one who had never done it asks to take the next one alone.","debrief":"Bringing information back from the PLC is a real job, not a formality. Sorting it by what the patrol has to decide tonight is what makes it useful instead of noise.","edge_focus":"enable"},"next-week":{"id":"next-week","type":"outcome","prompt":"At the next meeting two scouts find out the campout moved by hearing their parents talk about it. The service project runs two scouts short.","debrief":"A patrol that hears things late stops planning around them at all. Most of the fix is deciding what has to be said out loud tonight and what can go in a message."}}}'::jsonb
  ),
  (
    'plc-runs-long',
    'training'::public.scenario_kind,
    'The PLC That Will Not End',
    'Forty minutes in, one patrol leader has used most of them.',
    'Sunday evening PLC, planning the next month',
    array['SPL']::public.leadership_role[],
    array['star', 'life', 'eagle']::public.scout_rank[],
    array['communication', 'planning', 'delegation']::text[],
    4,
    '{"version":1,"root":"forty-minutes","nodes":{"forty-minutes":{"id":"forty-minutes","type":"decision","prompt":"The PLC is scheduled for an hour. You are forty minutes in and have covered one of five agenda items, because Marcus has re-argued the campout destination four times. Two patrol leaders have stopped talking entirely and one is on his phone.","choices":[{"id":"let-it-run","text":"Let it play out. Marcus cares about this and cutting him off would be rude.","deltas":{"planning":-3,"delegation":-1},"coaching":{"text":"Protecting one scout from being interrupted is costing four others their agenda items. Running the meeting is your job and nobody else at the table can do it.","principle":"Airtime is a resource you allocate"},"next":"overtime"},{"id":"time-box-it","text":"Say, \"Marcus, two more minutes on this, then we vote and move to the November calendar.\"","deltas":{"planning":3,"communication":3},"coaching":{"text":"A time box plus a named next step ends it without ending him — he knows exactly how much runway he has. Saying the vote is coming makes the two minutes about persuading, not repeating.","principle":"Time box, then decide"},"next":"after-box"},{"id":"shut-him-down","text":"Say, \"Marcus, we have heard you. Moving on,\" and go to the next item.","deltas":{"planning":2,"conflict_resolution":-2},"coaching":{"text":"The agenda is moving again and it cost you the most engaged person in the room. He will bring it back outside the meeting, where you cannot manage it.","principle":"Cut the topic, not the person"},"next":"after-box"},{"id":"ask-the-quiet","text":"Say, \"Before we settle this — Devon, Priya, you two have not said anything. What do your patrols want?\"","deltas":{"communication":3,"delegation":2,"conflict_resolution":1},"coaching":{"text":"Bringing in the quiet leaders usually ends a circular argument faster than cutting off the loud one, because the loop was being sustained by having no new input. It also reminds the table that they represent patrols.","principle":"Add voices to end a loop"},"next":"after-box"}]},"after-box":{"id":"after-box","type":"decision","prompt":"The destination gets settled. You have eighteen minutes and four agenda items: November calendar, meeting segment assignments, the recruiting night, and a gear inventory nobody has done.","choices":[{"id":"rush-all-four","text":"Push through all four in eighteen minutes.","deltas":{"planning":-1,"communication":-1},"coaching":{"text":"Four items in eighteen minutes produces four decisions nobody can repeat on Tuesday. A meeting that covers everything and lands nothing is the expensive kind.","principle":"Cover less, land it"},"next":"thin-decisions"},{"id":"triage-agenda","text":"Say, \"Calendar and segments now, because they block everyone. Recruiting night and gear go to two people who bring a proposal next PLC.\"","deltas":{"planning":3,"delegation":3},"coaching":{"text":"Deciding what does not need the whole table is the part of running a PLC that nobody teaches. Two scouts with a proposal beat eighteen rushed minutes of six people.","edge_stage":"enable","principle":"Not everything needs the table"},"next":"landed-plc"},{"id":"extend-meeting","text":"Extend the meeting by half an hour to get through everything.","deltas":{"planning":-2,"communication":-1},"coaching":{"text":"You can, once. Do it twice and patrol leaders start finding reasons not to come, and a PLC people avoid is worse than a short one.","principle":"Protect the end time"},"next":"thin-decisions"}]},"landed-plc":{"id":"landed-plc","type":"outcome","prompt":"The PLC ends four minutes early with two decisions everyone can repeat and two owners assigned. Marcus catches you after and says the destination thing was fair.","debrief":"An SPL who runs a tight PLC gets patrol leaders who show up. The main levers are a time box, a named decision point, and moving work off the table to individuals.","edge_focus":"enable"},"thin-decisions":{"id":"thin-decisions","type":"outcome","prompt":"The meeting ends. On Tuesday two patrol leaders have different ideas about what was decided on segments, and the gear inventory still has no owner.","debrief":"A decision without a named owner and a date is a topic that was discussed. Most of what a PLC produces should be somebody''s name next to something."},"overtime":{"id":"overtime","type":"outcome","prompt":"The PLC runs eighty minutes, gets through two items, and two patrol leaders leave early. The next one has three people at it.","debrief":"Nobody quits a PLC because of one long meeting. They quit because of three, and the SPL is the only person in the room who can prevent that."}}}'::jsonb
  ),
  (
    'patrol-leader-not-leading',
    'training'::public.scenario_kind,
    'The PL Who Is Not Leading',
    'One patrol is falling apart and its leader is not doing the job.',
    'Two months into the term',
    array['SPL']::public.leadership_role[],
    array['star', 'life', 'eagle']::public.scout_rank[],
    array['delegation', 'conflict_resolution']::text[],
    5,
    '{"version":1,"root":"the-pattern","nodes":{"the-pattern":{"id":"the-pattern","type":"decision","prompt":"The Hawk patrol has not had a duty roster in three campouts. Their gear comes back dirty. Two of their scouts have started sitting with other patrols at meetings. Their PL, Brandon, was elected in a landslide and is well liked, and every time you have seen him he is friendly and says it is fine.","choices":[{"id":"run-their-patrol","text":"Start assigning the Hawk patrol''s jobs yourself at campouts so at least the work gets done.","deltas":{"delegation":-3,"initiative":1},"coaching":{"text":"The work gets done and Brandon is now formally irrelevant in his own patrol, in front of his scouts. An SPL who steps over a PL takes the whole troop''s patrol method with it.","principle":"Never lead a patrol around its leader"},"next":"undermined"},{"id":"ask-brandon","text":"Sit down with Brandon alone and ask him what the hardest part of the job has been.","deltas":{"communication":3,"conflict_resolution":2,"delegation":1},"coaching":{"text":"Asking what is hard gets you further than asking why the roster is missing, because it does not require him to admit failure first. Most struggling PLs know exactly what is wrong.","edge_stage":"guide","principle":"Ask what is hard, not what is wrong"},"next":"brandon-opens"},{"id":"tell-scoutmaster","text":"Tell the Scoutmaster that Brandon is not doing the job and ask him to handle it.","deltas":{"initiative":-2,"delegation":-1},"coaching":{"text":"Coaching patrol leaders is the core of the SPL job — this is the thing, not a distraction from it. Bring the Scoutmaster in after you have tried, and with specifics.","principle":"Coaching PLs is the SPL job"},"next":"undermined"},{"id":"public-standard","text":"At the next PLC, announce that every patrol will show a duty roster before departure from now on.","deltas":{"planning":2,"communication":1,"conflict_resolution":-1},"coaching":{"text":"A troop-wide standard is a fair way to raise the floor without naming anyone. Everyone in that room will know exactly who it is aimed at, so it does not replace the conversation.","principle":"A rule aimed at one person is still aimed"},"next":"brandon-opens"}]},"brandon-opens":{"id":"brandon-opens","type":"decision","prompt":"Brandon takes a while. Then: \"I do not know how to make people do stuff. Like, Jake just does not listen to me and everyone knows it, so if I make the roster and he ignores it I look worse than if there is no roster.\"","choices":[{"id":"tell-him-to-be-firm","text":"Tell him he needs to be more assertive and hold his patrol accountable.","deltas":{"communication":-2,"delegation":-1},"coaching":{"text":"\"Be more assertive\" is a description of the outcome, not an instruction he can act on. He just told you the specific thing he is afraid of and it deserves a specific answer.","principle":"Advice has to be a next action"},"next":"no-change"},{"id":"one-concrete-step","text":"Say, \"Forget the whole patrol. This week you do one thing: post the roster before we leave the lot and read it out loud. That is it. I will be standing there.\"","deltas":{"delegation":3,"communication":3,"planning":2},"coaching":{"text":"One narrow action he can actually complete beats a general call to lead better. Standing there is the guide step — present, not doing it for him.","edge_stage":"guide","principle":"One action, this week"},"next":"jake-problem"},{"id":"swap-him-out","text":"Tell him it might be better if he stepped down and let the APL take over.","deltas":{"conflict_resolution":-2,"delegation":-2},"coaching":{"text":"Two months in, with a scout who just told you honestly what he is struggling with, is early to remove someone. Position of responsibility is supposed to be where a scout learns this.","principle":"The position is where they learn it"},"next":"no-change"}]},"jake-problem":{"id":"jake-problem","type":"decision","prompt":"The roster goes up Friday. Saturday, Jake skips his assignment in front of everyone and says, loudly, \"Brandon is not my boss.\" Brandon looks at you.","choices":[{"id":"step-in-directly","text":"Step in and tell Jake to do his job.","deltas":{"conflict_resolution":1,"delegation":-3},"coaching":{"text":"It works right now and proves Brandon cannot make Jake do anything without you. You have confirmed the exact belief that started the problem.","principle":"Solving it for him proves his fear"},"next":"undermined"},{"id":"back-him-quietly","text":"Catch Brandon''s eye, stay put, and afterwards tell him what you saw and what you would say to Jake next.","deltas":{"delegation":3,"conflict_resolution":3,"communication":2},"coaching":{"text":"Not stepping in is the hardest and most valuable thing you do here — it leaves the authority where it belongs. The debrief after is where the actual teaching happens.","edge_stage":"guide","principle":"Stay out of it, then coach it"},"next":"slow-turn"},{"id":"talk-to-jake-later","text":"Say nothing now. Later, talk to Jake alone about how a patrol works, without mentioning Brandon.","deltas":{"conflict_resolution":2,"delegation":1,"communication":1},"coaching":{"text":"Handling Jake out of sight avoids undercutting Brandon in the moment, which is the main risk. Be careful it does not become you quietly running his patrol from behind.","principle":"Quiet help is still help you have to taper"},"next":"slow-turn"}]},"slow-turn":{"id":"slow-turn","type":"outcome","prompt":"It takes six weeks. The rosters go up every trip, Jake tests it twice more and then stops, and the two scouts who were drifting come back. Brandon is still not a great PL. He is a functioning one.","debrief":"Coaching a patrol leader is slow and the results are never dramatic. The measure is whether the patrol works when you are not standing there, not whether it looks good this weekend.","edge_focus":"guide"},"undermined":{"id":"undermined","type":"outcome","prompt":"The Hawk patrol''s work gets done when you are watching. Brandon stops coming to the PLC, and at the next election two scouts run for PL of other patrols rather than his.","debrief":"An SPL who fixes patrols directly gets a troop of patrols that only run when the SPL is present. That is a harder problem than one weak roster."},"no-change":{"id":"no-change","type":"outcome","prompt":"Nothing much changes. Brandon finishes his term quietly, the patrol stays loose, and he does not run for anything again.","debrief":"General advice feels like coaching and changes nothing. The difference is whether the scout leaves the conversation with one specific thing to do before the next campout."}}}'::jsonb
  ),
  (
    'service-project-short',
    'training'::public.scenario_kind,
    'Half the Volunteers',
    'Nine scouts signed up for the service project. Four showed up.',
    '8:05 Saturday morning, county park trailhead',
    array['SPL', 'PL']::public.leadership_role[],
    array['first_class', 'star', 'life', 'eagle']::public.scout_rank[],
    array['planning', 'initiative']::text[],
    4,
    '{"version":1,"root":"headcount","nodes":{"headcount":{"id":"headcount","type":"decision","prompt":"The park ranger is expecting nine scouts to clear two hundred yards of trail and rebuild three water bars. It is 8:05 and you have four scouts, two adults, and the ranger walking over with a clipboard.","choices":[{"id":"start-and-hope","text":"Start on the original plan and hope some more show up.","deltas":{"planning":-2,"initiative":1},"coaching":{"text":"Starting beats standing around, so the instinct is not wrong. Committing four scouts to a nine-scout plan means you finish nothing rather than something.","principle":"Do not spread four across nine"},"next":"noon"},{"id":"rescope-with-ranger","text":"Meet the ranger first: \"We are four instead of nine. What is the one piece that matters most if we only get one thing done?\"","deltas":{"planning":3,"communication":3,"initiative":2},"coaching":{"text":"The person who owns the trail knows which two hundred yards matter, and asking makes them a partner instead of someone being let down. Rescoping at 8:05 is normal project work, not failure.","principle":"Rescope early and out loud"},"next":"the-work"},{"id":"chase-the-missing","text":"Spend the first half hour calling and texting the five who did not show.","deltas":{"planning":-2,"initiative":-1},"coaching":{"text":"You will get two answers and neither will be here before ten. The four scouts who did show are standing in a parking lot watching you work the phone.","principle":"Lead who showed up"},"next":"noon"}]},"the-work":{"id":"the-work","type":"decision","prompt":"The ranger says the water bars are what actually matter — the trail clearing is cosmetic. Three water bars, four scouts, and one of them is a Tenderfoot who has never used a McLeod.","choices":[{"id":"split-solo","text":"Put one scout on each water bar and take the third yourself, so all three go at once.","deltas":{"delegation":1,"planning":-1},"coaching":{"text":"Three parallel jobs finishes faster on paper. The scout who has never done it builds one badly and unsupervised, which is the one the ranger has to redo.","principle":"Parallel is not always faster"},"next":"noon"},{"id":"teach-then-split","text":"Build the first one together with everyone watching, then split into two pairs for the other two.","deltas":{"planning":3,"delegation":3,"communication":2},"coaching":{"text":"One demonstration up front costs twenty minutes and saves two rebuilds, and everyone can see the standard. Pairing the Tenderfoot rather than leaving him solo is the guide step.","edge_stage":"demonstrate","principle":"Teach once, then parallelise"},"next":"finished"},{"id":"keep-new-scout-off","text":"Give the Tenderfoot the water jug and trash bags so the experienced scouts can work fast.","deltas":{"delegation":-2,"initiative":-1},"coaching":{"text":"He came at seven in the morning to do trail work and got handed a trash bag. That is the service project he will remember when the next one gets announced.","principle":"Do not park the new scout"},"next":"noon"}]},"finished":{"id":"finished","type":"outcome","prompt":"Three water bars are in by 11:40, built the same way. The ranger walks them, says they will hold, and asks if the troop wants the trail section again in the spring.","debrief":"A project that is half staffed is a scoping problem, not a doomed day. Ask the owner what matters, cut to that, and teach once before you split up.","edge_focus":"demonstrate"},"noon":{"id":"noon","type":"outcome","prompt":"At noon there is one finished water bar, one half-built, and about eighty yards of cleared trail. The ranger is polite about it.","debrief":"Four scouts can do real work in four hours. What burns the morning is trying to run the plan that was written for nine."}}}'::jsonb
  ),
  (
    'recruiting-night',
    'training'::public.scenario_kind,
    'Crossover Night',
    'Fifteen Webelos and their parents are coming and your troop is not ready.',
    'Tuesday meeting, one week before the crossover visit',
    array['SPL', 'PL']::public.leadership_role[],
    array['star', 'life', 'eagle']::public.scout_rank[],
    array['planning', 'delegation', 'initiative']::text[],
    4,
    '{"version":1,"root":"one-week","nodes":{"one-week":{"id":"one-week","type":"decision","prompt":"Fifteen Webelos and most of their parents are visiting next Tuesday. Right now the troop''s meetings run about twenty minutes late, the meeting room has two broken patrol boxes stacked in the corner, and last time a visiting family came, three scouts ran a dodgeball game and the parents watched from the wall.","choices":[{"id":"adults-handle-it","text":"The committee usually handles recruiting. Let them plan it.","deltas":{"initiative":-3,"delegation":-1},"coaching":{"text":"Parents decide based on whether the scouts look like they run the troop. An adult-run recruiting night quietly answers the question the families came to ask.","principle":"They are watching who runs it"},"next":"the-night"},{"id":"plan-the-night","text":"Take twenty minutes of tonight''s PLC to plan it: who greets at the door, what the Webelos actually do for an hour, and who talks to parents.","deltas":{"planning":3,"initiative":3,"delegation":2},"coaching":{"text":"Naming the three jobs is most of the work — door, activity, parents — because each one fails differently if nobody owns it. An hour of Webelos doing something beats an hour of them watching something.","principle":"Name the jobs, not the theme"},"next":"assigning"},{"id":"do-a-normal-meeting","text":"Run a completely normal meeting so the families see what the troop is actually like.","deltas":{"planning":-1,"communication":1},"coaching":{"text":"Being honest about what the troop is like is a defensible call and beats staging something fake. A normal meeting that starts twenty minutes late shows them something you probably did not intend.","principle":"Honest still means prepared"},"next":"assigning"}]},"assigning":{"id":"assigning","type":"decision","prompt":"You have the jobs. Now the people: your two most confident scouts always end up doing the talking, and both are busy that night with a merit badge session.","choices":[{"id":"take-it-yourself","text":"Take the door and the parent conversation yourself. You are the SPL, and it matters.","deltas":{"delegation":-3,"initiative":1},"coaching":{"text":"You will do it well and you can only be in one place. The visiting families will meet the SPL and not much of the troop.","principle":"You cannot be three places"},"next":"the-night"},{"id":"newer-scouts-with-script","text":"Give the door and the Webelos activity to two first-year scouts, and spend ten minutes at Tuesday''s meeting walking them through exactly what to say and do.","deltas":{"delegation":3,"communication":3,"planning":2},"coaching":{"text":"First-year scouts are the ones the Webelos will actually relate to, and ten minutes of explain-and-demonstrate is what makes it safe to hand them. Pre-briefing is not scripting them, it is removing the guessing.","edge_stage":"explain","principle":"Prepare people you have never used"},"next":"the-night-ready"},{"id":"wing-the-assignments","text":"Assign the jobs Tuesday night when you see who is there.","deltas":{"planning":-2,"delegation":1},"coaching":{"text":"Assigning on the night means nobody arrives having thought about it. The jobs get filled and each one gets done at whatever quality the first available scout can manage cold.","principle":"Assign before the night"},"next":"the-night"}]},"the-night-ready":{"id":"the-night-ready","type":"outcome","prompt":"Two first-year scouts run the door and a fire-building relay. The Webelos spend the hour doing things. Nine of the fifteen families come back in March.","debrief":"Recruiting is a planning and delegation problem wearing a different hat. The visiting families are mostly deciding whether the scouts here look like they are running something.","edge_focus":"explain"},"the-night":{"id":"the-night","type":"outcome","prompt":"The meeting starts fifteen minutes late. The Webelos sit along the wall with their parents for most of it, and four families come back in March.","debrief":"Nothing went wrong exactly. The families just did not see anything that told them their son would have something to do here in six months."}}}'::jsonb
  )
on conflict (id) do update set
  kind = excluded.kind,
  title = excluded.title,
  summary = excluded.summary,
  setting = excluded.setting,
  role_relevance = excluded.role_relevance,
  rank_relevance = excluded.rank_relevance,
  primary_dimensions = excluded.primary_dimensions,
  estimated_minutes = excluded.estimated_minutes,
  branching_tree = excluded.branching_tree,
  is_published = true;
